function boundsOfRing(pts) {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of pts) {
    if (p.x < minX) minX = p.x;
    if (p.x > maxX) maxX = p.x;
    if (p.z < minZ) minZ = p.z;
    if (p.z > maxZ) maxZ = p.z;
  }
  return { minX, maxX, minZ, maxZ };
}
const HARBOUR_COASTLINES = ((GEO.harbour && GEO.harbour.rings) || []).map(toPts);
// Island + Kowloon + Victoria Harbour. The island ring alone is not the playable coast.
const ISLAND_BOUNDS = (() => {
  const boxes = [
    boundsOfRing(HONG_KONG_ISLAND_COASTLINE),
    boundsOfRing(KOWLOON_COASTLINE),
    ...HARBOUR_COASTLINES.map(boundsOfRing)
  ].filter((b) => Number.isFinite(b.minX));
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const b of boxes) {
    minX = Math.min(minX, b.minX);
    maxX = Math.max(maxX, b.maxX);
    minZ = Math.min(minZ, b.minZ);
    maxZ = Math.max(maxZ, b.maxZ);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.2 };
})();
const PLAY_BOUNDS = ISLAND_BOUNDS;

// Legacy midtown landmark block registry (`${col}_${row}` on AVENUES x STREETS): landmarks now stand on their real
// lots (LANDMARK_SITES), so nothing is reserved on the old superblock grid
const LANDMARK_BLOCKS = new Set();

/**
 * Buildable footprint of the old midtown superblock (col, row) between AVENUES[col..col+1] and STREETS[row..row+1]
 * (at real positions: several real blocks)
 */
function getBlockBounds(col, row) {
  const westAve = AVENUES[col];
  const eastAve = AVENUES[col + 1];
  const northSt = STREETS[row];
  const southSt = STREETS[row + 1];
  if (!westAve || !eastAve || !northSt || !southSt) {
    const minX = col * 80;
    const minZ = row * 80;
    return {
      col, row, minX, maxX: minX + 60, minZ, maxZ: minZ + 50,
      cx: minX + 30, cz: minZ + 25, width: 60, depth: 50,
      sidewalkMinX: minX, sidewalkMaxX: minX + 60, sidewalkMinZ: minZ, sidewalkMaxZ: minZ + 50
    };
  }
  const minX = westAve.x + westAve.width * 0.5 + westAve.sidewalk;
  const maxX = eastAve.x - eastAve.width * 0.5 - eastAve.sidewalk;
  const minZ = northSt.z + northSt.width * 0.5 + northSt.sidewalk;
  const maxZ = southSt.z - southSt.width * 0.5 - southSt.sidewalk;
  return {
    col, row, minX, maxX, minZ, maxZ,
    cx: (minX + maxX) * 0.5,
    cz: (minZ + maxZ) * 0.5,
    width: maxX - minX,
    depth: maxZ - minZ,
    sidewalkMinX: westAve.x + westAve.width * 0.5,
    sidewalkMaxX: eastAve.x - eastAve.width * 0.5,
    sidewalkMinZ: northSt.z + northSt.width * 0.5,
    sidewalkMaxZ: southSt.z - southSt.width * 0.5
  };
}

/**
 * Exact street / avenue / landmark name at any world (x, z): the nearest roads of the real street centreline
 */
function getLocationLabel(x, z) {
  if (GEO.frame.city === 'hk') {
    for (const lm of NYC_LANDMARKS) {
      if (Math.hypot(x - lm.x, z - lm.z) < 160) {
        const near = nearestRoads(x, z, 90);
        return near.length ? `${lm.name} · ${near[0].road.name}` : lm.name;
      }
    }
    const near = nearestRoads(x, z, 40);
    if (near.length && near[0].dist < near[0].road.w) return near[0].road.name;
    if (pointInPoly(MANHATTAN_COASTLINE, x, z)) return '香港島';
    if (KOWLOON_COASTLINE.length && pointInPoly(KOWLOON_COASTLINE, x, z)) return '九龍';
    return '維多利亞港';
  }
  for (const lm of NYC_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) {
      const near = nearestRoads(x, z, 120);
      const ave = near.find((r) => !r.horizontal);
      const st = near.find((r) => r.horizontal);
      return `${lm.name}${ave && st ? ` · ${ave.road.name} & ${st.road.name}` : ''}`;
    }
  }
  const cp = CENTRAL_PARK_BOUNDS;
  if (x > cp.minX && x < cp.maxX && z > cp.minZ && z < cp.maxZ) {
    const st = ALL_STREETS.reduce((a, s) => (s.number && Math.abs(s.z - z) < Math.abs(a.z - z) ? s : a), ALL_STREETS[0]);
    return `Central Park · near ${st.short}`;
  }
  const shore = getIslandBoundsAtZ(z);
  const near = nearestRoads(x, z, 160);
  const ave = near.find((r) => !r.horizontal);
  const st = near.find((r) => r.horizontal);
  if (z > CUT_Z && (x < shore.westX + 30 || x > shore.eastX - 30)) {
    return `${x < (shore.westX + shore.eastX) / 2 ? 'Hudson River' : 'East River'} Waterfront${st ? ` · near ${st.road.name}` : ''}`;
  }
  if (ave && st) return `${ave.road.name} & ${st.road.name}`;
  if (near.length) return near[0].road.name;
  return 'New York Harbor';
}

/**
 * A point authored in the simulation's former compressed frame (old Manhattan coordinates: avenues every ~110 units,
 * Midtown streets every 90) -> the real 1:1 frame, through the old avenue & street positions: piecewise linear between
 * them, but offsets within an avenue's / street's roadway (|d| < 20 old units) stay in metres, so a point "6 m east of
 * 5th Ave's centreline" stays 6 m east of it.
 */
const OLD_AVE_X = [[-620, -1960], [-545, -1683], [-475, -1408], [-403, -1134], [-330, -860], [-220, -585], [-110, -310], [0, 0],
  [110, 311], [220, 467], [330, 622], [416, 838], [494, 1067], [560, 1284], [609, 1507], [648, 1734]];
const OLD_ST_Z = [[-1566, 125], [-1296, 110], [-1044, 96], [-864, 86], [-738, 79], [-612, 72], [-378, 59], [-360, 58], [-315, 56],
  [-270, 53], [-225, 50], [-180, 48], [-135, 46], [-90, 45], [-45, 43], [0, 42], [45, 40], [90, 38], [135, 36], [180, 34], [225, 31],
  [270, 28], [315, 26], [360, 23], [402, 20], [440, 18], [483, 16], [529, 14], [575, 11], [623, 8], [671, 4], [722, 1]]
  .map(([oz, n]) => [oz, streetZ(n)]).concat([[778, 3376], [974, 4169], [1148, 4859], [1252, 5291], [1356, 5703], [1432, 6119], [1480, 6510]]);
function oldAxis(table, v, keepWithin = 20, rowScale = 1) {
  let best = null;
  for (const [o, r] of table) if (!best || Math.abs(v - o) < Math.abs(v - best[0])) best = [o, r];
  // within the old roadway + sidewalk: the same place across the (narrower) real right-of-way
  if (Math.abs(v - best[0]) < keepWithin) return best[1] + (v - best[0]) * rowScale;
  for (let i = 0; i + 1 < table.length; i++) {
    const [a0, b0] = table[i];
    const [a1, b1] = table[i + 1];
    if (v >= a0 && v <= a1) return b0 + ((v - a0) / (a1 - a0)) * (b1 - b0);
  }
  const [a0, b0] = v < table[0][0] ? table[0] : table[table.length - 2];
  const [a1, b1] = v < table[0][0] ? table[1] : table[table.length - 1];
  return b0 + ((v - a0) / (a1 - a0)) * (b1 - b0);
}
// (old avenues: 26 m roadway + 6.5 m sidewalks -> real ~15-21 m + 4.6 m; old streets 18 + 4.5 -> ~9.5 + 4.6)
const fromOldFrame = (x, z) => ({ x: oldAxis(OLD_AVE_X, x, 20, 0.6), z: oldAxis(OLD_ST_Z, z, 14, 0.68) });

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds:
// avenues green until avenueAmber, amber until avenueRed; cross streets green from avenueRed until streetAmber,
// amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off
// only on the WALK, the first `walk` seconds of its green: long enough before the cross traffic's green for the
// slowest walker to get across the widest avenue.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for avenue or cross street traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside avenue (or cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

